// ─── PayrollPro: Login Handler ───
// Reads credentials from the request, validates against the users store
// stored in workflow static data, and returns a session token on success.
//
// HOW TO CUSTOMISE:
//   Replace the staticData users store with your own database lookup
//   (e.g. Postgres, MySQL, Airtable, Google Sheets) by swapping out
//   the validation block below.

const store = $getWorkflowStaticData('global');

// ── Seed default admin user on first run ──
if (!store.users || store.users.length === 0) {
  store.users = [
    {
      id: 'U001',
      email: 'admin@company.com',
      password: 'admin123',   // ← change in production!
      name: 'Admin User',
      role: 'admin',
      companyName: 'My Company'
    }
  ];
}

const body = $input.first().json.body;
const { email, password } = body.data || {};

if (!email || !password) {
  return [{ json: { success: false, message: 'Email and password are required.' } }];
}

const user = store.users.find(
  u => u.email.toLowerCase() === email.toLowerCase() && u.password === password
);

if (!user) {
  return [{ json: { success: false, message: 'Invalid email or password.' } }];
}

// Generate a simple session token (replace with JWT in production)
const token = 'sess_' + Date.now() + '_' + Math.random().toString(36).slice(2, 10);

return [{
  json: {
    success: true,
    message: 'Login successful',
    data: {
      token,
      userId:      user.id,
      name:        user.name,
      email:       user.email,
      role:        user.role,
      companyName: user.companyName || 'My Company',
      expiresAt:   Date.now() + 8 * 60 * 60 * 1000  // 8-hour session
    }
  }
}];

const store = $getWorkflowStaticData('global');
if (!store.employees) store.employees = [];

const emp = $input.first().json.body.data;
if (!emp || !emp.employeeId) {
  return [{ json: { success: false, message: 'Missing employee data.' } }];
}

const idx = store.employees.findIndex(e => e.employeeId === emp.employeeId);
if (idx >= 0) {
  store.employees[idx] = emp;
} else {
  store.employees.push(emp);
}

return [{ json: { success: true, data: emp, message: idx >= 0 ? 'Employee updated.' : 'Employee created.' } }];

const store = $getWorkflowStaticData('global');
if (!store.employees) store.employees = [];

const { employeeId } = $input.first().json.body.data || {};
if (!employeeId) return [{ json: { success: false, message: 'Missing employeeId.' } }];

store.employees = store.employees.filter(e => e.employeeId !== employeeId);
if (store.attendance) store.attendance = store.attendance.filter(a => a.employeeId !== employeeId);

return [{ json: { success: true, message: 'Employee deleted.' } }];

const store = $getWorkflowStaticData('global');
if (!store.attendance) store.attendance = [];

const rec = $input.first().json.body.data;
if (!rec || !rec.id) return [{ json: { success: false, message: 'Missing attendance data.' } }];

const idx = store.attendance.findIndex(a => a.id === rec.id);
if (idx >= 0) {
  store.attendance[idx] = rec;
} else {
  store.attendance.push(rec);
}

return [{ json: { success: true, data: rec, message: 'Attendance saved.' } }];

const store = $getWorkflowStaticData('global');
const { month } = $input.first().json.body.data || {};
const records = store.attendance || [];
const filtered = month ? records.filter(r => r.date && r.date.startsWith(month)) : records;
return [{ json: { success: true, data: filtered } }];

const store = $getWorkflowStaticData('global');
if (!store.attendance) store.attendance = [];

const { id } = $input.first().json.body.data || {};
if (!id) return [{ json: { success: false, message: 'Missing id.' } }];

const before = store.attendance.length;
store.attendance = store.attendance.filter(a => a.id !== id);
const deleted = before - store.attendance.length;

return [{ json: { success: true, message: deleted > 0 ? 'Record deleted.' : 'Record not found.' } }];

const store = $getWorkflowStaticData('global');
if (!store.payrolls) store.payrolls = [];

const body = $input.first().json.body;
const { month, payrolls: incoming } = body.data || {};

if (!month || !incoming) return [{ json: { success: false, message: 'Missing month or payroll data.' } }];

// Remove existing payroll for this month and replace with new
store.payrolls = store.payrolls.filter(p => p.month !== month);
store.payrolls.push(...incoming);

return [{ json: { success: true, data: incoming, message: `Payroll saved for ${month}.` } }];

const store = $getWorkflowStaticData('global');
const { month } = $input.first().json.body.data || {};
const records = store.payrolls || [];
const filtered = month ? records.filter(p => p.month === month) : records;
return [{ json: { success: true, data: filtered } }];
